const $ = (id) => document.getElementById(id);
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = (n) => Number(n || 0).toLocaleString('en-US');
const stationLabel = (value) => {const raw=String(value||'').trim();return !raw?'Station open':/^~?\s*[\d,]+(?:\.\d+)?$/.test(raw)?`${raw} ft`:raw};
const scopeOf = (id) => id?.startsWith('S0-') ? 'S0' : id?.startsWith('S1-') ? 'S1' : id?.startsWith('Spur') ? 'Chicago' : 'All';
const routeColors = {S0:'#b9ec70',S1:'#48c7dc',Spur1:'#7298ff',Spur2:'#7298ff',Spur3:'#7298ff',Spur4:'#7298ff'};
const layerUrls = {routes:'data/routes.geojson',row:'data/row.geojson',utilities:'data/utilities.geojson',water:'data/water.geojson',rail:'data/rail.geojson',parcels:'data/parcels.geojson'};
const state = {scope:'S0',report:'overview',selected:null,base:'dark',data:{},layers:{},visible:{routes:true,row:true,utilities:true,water:true,rail:true,parcels:false},reportLimit:60,filtered:[],utilitySource:'all',utilityType:'all'};
const map = L.map('map',{zoomControl:false,preferCanvas:true,scrollWheelZoom:true}).setView([40.1,-82.95],10);
L.control.zoom({position:'bottomright'}).addTo(map);
const baseLayers = {
  dark:L.tileLayer('https://basemap.nationalmap.gov/arcgis/rest/services/USGSTopo/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,maxNativeZoom:16,className:'dark-tiles',attribution:'USGS The National Map'}),
  light:L.tileLayer('https://basemap.nationalmap.gov/arcgis/rest/services/USGSTopo/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,maxNativeZoom:16,attribution:'USGS The National Map'})
};
baseLayers.dark.addTo(map);

const watchlist = [
  {scope:'S0',feature:'S0-S014-HW',rank:'P0 · STATE ROW',title:'I-270 interchange control',body:'Access-control, ramp and ROW limits need ODOT plan confirmation.',report:'ahj'},
  {scope:'S0',feature:'S0-S025-Bore',rank:'P0 · STATE ROW',title:'US 23 / SR 750 corridor',body:'Long arterial reach with unresolved acquisition plans and road-side fit.',report:'missing'},
  {scope:'S0',feature:'S0-S021-Bore',rank:'P1 · UTILITIES',title:'Worthington utility density',body:'Public water, storm, sanitary, traffic and electric leads; linked historical plans.',report:'utilities'},
  {scope:'S1',feature:'S1-S033-Water',rank:'P0 · LAND RIGHTS',title:'O’Shaughnessy reservoir',body:'City water-supply property, bridge feasibility and channel rights are open.',report:'water'},
  {scope:'S1',feature:'S1-S029-Water',rank:'P0 · WATER / ROAD',title:'Olentangy crossing',body:'River, bridge and SR 315 approvals need a station-tied concept.',report:'water'},
  {scope:'S1',feature:'S1-S045-RR',rank:'P0 · RAIL',title:'CSX crossing rights',body:'Geometric rail crossing; valuation map and license signatory still needed.',report:'rail'},
  {scope:'Chicago',feature:'Spur1-S02-Water',rank:'P0 · WATER',title:'Salt Creek crossing',body:'Floodway, USACE, Illinois water approval and work-area limits remain open.',report:'water'},
  {scope:'Chicago',feature:'Spur3-S01-Bore',rank:'P0 · RAIL / ROAD',title:'Centex industrial rail',body:'CJR operating lead and UP property lead at multiple crossings.',report:'rail'},
  {scope:'Chicago',feature:'Spur4-S01-Bore',rank:'P1 · CAPITAL WORK',title:'Pratt utility work',body:'New roadway and water-main work needs current record plans and cut rules.',report:'ahj'}
];

const reports = {
  ahj:{title:'AHJ & permit candidates',subtitle:'1,362 station intervals across every route feature. Candidate issuer only until controlling road ROW and work limits are confirmed.',kicker:'AUTHORITY REGISTER',records:()=>state.data.reports.ahj,
    titleRow:r=>`${r.feature_id} · ${r.nearby_road_candidates_and_codes || 'Road authority open'}`,subRow:r=>`${r.station_start_ft_KMZ}–${r.station_end_ft_KMZ} ft · ${r.candidate_permit_issuer_not_confirmed || 'Confirm issuer'}`},
  water:{title:'Water & drainage cases',subtitle:'16 water, stream, reservoir or drainage leads. Jurisdiction and permit path depend on the surveyed design footprint.',kicker:'CROSSING REGISTER',records:()=>state.data.reports.water,
    titleRow:r=>`${String(r.water_name_or_issue||'').trim() || 'Unnamed water feature'} · ${r.feature_id}`,subRow:r=>`${stationLabel(r.feature_station_ft_from_KMZ_start)} · ${r.screening_confidence}`},
  rail:{title:'Rail crossing register',subtitle:'21 rail screen records, including 11 exact geometry crossing points. Operator codes do not establish ROW title or license signatory.',kicker:'CROSSING REGISTER',records:()=>state.data.reports.rail,
    titleRow:r=>`${r.reported_owner_or_operator_codes || 'Rail owner open'} · ${r.feature_id}`,subRow:r=>`${r.subdivision || 'Subdivision open'} · ${r.exact_geometry_intersection === 'Y' ? 'Geometric crossing' : 'Nearby lead'}`},
  utilities:{title:'Public utility screen',subtitle:'2,935 asset-to-route proximity links. Map positions and offsets are approximate; owner records and field locates remain necessary.',kicker:'UTILITY REGISTER',records:()=>state.data.reports.utilities,
    titleRow:r=>`${r.utility_type || 'Utility'} · ${r.feature_id}`,subRow:r=>`${r.source} · ${r.offset_ft_approx || '0'} ft approximate offset`},
  documents:{title:'PDF evidence library',subtitle:'183 validated source PDFs, 2,160 pages. The scans remain in the local evidence archive; official portal links appear where available. A plan or deed remains a lead until fitted to the work envelope.',kicker:'EVIDENCE LIBRARY',records:()=>state.data.reports.documents,
    titleRow:r=>r.document_title || r.document_id || r.relative_path,subRow:r=>`${r.route_area} · Grade ${r.evidence_grade_A_B_C || 'open'} · ${r.page_count} pages · ${r.route_features}`},
  missing:{title:'Open ROW records',subtitle:'94 indexed missing scan entries or record groups. These are acquisition targets, not a count of distinct legal instruments.',kicker:'RETRIEVAL QUEUE',records:()=>state.data.reports.missing,
    titleRow:r=>`${r.reference_id} · ${r.reference_type}`,subRow:r=>`${r.route_area} · ${r.custodian}`}
};

function toast(message){const el=$('mapToast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200)}
function displayScope(part){return state.scope==='All'||part===state.scope||state.scope==='Chicago'&&part?.startsWith('Spur')}
function featureFor(id){return state.data.routes?.features.find(f=>f.properties.feature_id===id)}
function fitScope(){const feats=state.data.routes?.features.filter(f=>displayScope(f.properties.route_part))||[];if(!feats.length)return;const bounds=L.geoJSON({type:'FeatureCollection',features:feats}).getBounds();map.fitBounds(bounds.pad(.13),{maxZoom:12,animate:true});}
function routeStyle(f){let color=routeColors[f.properties.route_part]||'#b9ec70';let inScope=displayScope(f.properties.route_part);let selected=state.selected===f.properties.feature_id;return {color,weight:selected?8:5,opacity:selected?1:inScope?.94:.19,lineCap:'round',lineJoin:'round',className:selected?'selected-route':''}}
function redrawRouteStyle(){state.layers.routes?.eachLayer(layer=>layer.setStyle(routeStyle(layer.feature)))}
function htmlLink(url,label){const first=String(url||'').split(';')[0].trim();return /^https?:\/\//i.test(first)?`<a href="${esc(first)}" target="_blank" rel="noopener noreferrer">${esc(label||'Open official source')} ↗</a>`:''}
function popup(title,fields,link){return `<strong>${esc(title)}</strong><br>${fields.filter(x=>x[1]).map(x=>`<small>${esc(x[0])}</small> ${esc(x[1])}<br>`).join('')}${link?htmlLink(link,'Open source'):''}`}
function typeColor(type){let t=String(type||'').toLowerCase();if(t.includes('storm')||t.includes('drain'))return '#7298ff';if(t.includes('sanitary')||t.includes('sewer')||t.includes('wastewater'))return '#ffb567';if(t.includes('electric'))return '#ff7991';if(t.includes('traffic')||t.includes('light'))return '#d39cf2';return '#48c7dc'}
function utilityMatches(f){const p=f.properties;if(state.utilitySource!=='all'&&!String(p.source).toLowerCase().includes(state.utilitySource))return false;const t=String(p.type||'').toLowerCase();switch(state.utilityType){case 'water':return t.includes('water')&&!t.includes('storm')&&!t.includes('wastewater');case 'sanitary':return t.includes('sanitary')||t.includes('sewer')||t.includes('wastewater');case 'storm':return t.includes('storm')||t.includes('drain');case 'traffic':return t.includes('traffic')||t.includes('light');case 'electric':return t.includes('electric');default:return true}}
function addLayer(name){if(!state.data[name])return;if(state.layers[name])map.removeLayer(state.layers[name]);const data=state.data[name];let layer;
  if(name==='routes')layer=L.geoJSON(data,{style:routeStyle,onEachFeature:(f,l)=>{l.on('click',()=>selectFeature(f.properties.feature_id,true));l.bindTooltip(f.properties.feature_id,{sticky:true})}});
  if(name==='parcels')layer=L.geoJSON(data,{style:()=>({color:'#91a9c8',weight:.7,opacity:.55,fillColor:'#5475a1',fillOpacity:.12}),onEachFeature:(f,l)=>{const p=f.properties;l.bindPopup(popup(`Parcel ${p.parcel_id}`,[['County',p.county],['Owner',p.owner],['Route',p.route_features],['Record',p.record]]));l.on('mouseover',()=>l.setStyle({weight:2,fillOpacity:.25}));l.on('mouseout',()=>state.layers.parcels?.resetStyle(l))}});
  if(name==='row')layer=L.geoJSON(data,{style:()=>({color:'#a4e2a0',weight:1,opacity:.8,fillColor:'#94d89d',fillOpacity:.17}),onEachFeature:(f,l)=>{const p=f.properties;l.bindPopup(popup(p.source,[['Reference',p.reference||'Not indexed'],['Name',p.name],['Job',p.job_no],['Status',p.status]]))}});
  if(name==='utilities')layer=L.geoJSON(data,{filter:utilityMatches,style:f=>({color:typeColor(f.properties.type),weight:2,opacity:.82}),pointToLayer:(f,ll)=>L.circleMarker(ll,{radius:4,color:typeColor(f.properties.type),weight:1,fillColor:typeColor(f.properties.type),fillOpacity:.9}),onEachFeature:(f,l)=>{const p=f.properties;l.bindPopup(popup(p.type,[['Source',p.source],['Asset',p.asset_id],['Near feature',p.feature_id],['Offset',p.offset_ft?`${Math.round(p.offset_ft)} ft approx.`:''],['Status',p.status]],p.plan_url||p.source_url))}});
  if(name==='water'||name==='rail')layer=L.geoJSON(data,{pointToLayer:(f,ll)=>L.marker(ll,{icon:L.divIcon({className:'',html:`<div class="map-marker ${name}" style="height:25px;width:25px">${name==='water'?'≈':'╋'}</div>`,iconSize:[25,25],iconAnchor:[12,12]})}),onEachFeature:(f,l)=>{const p=f.properties;l.bindPopup(name==='water'?popup(p.name,[['Feature',p.feature_id],['Station',p.station_ft===null?p.location_note:`${p.station_ft} ft`],['Confidence',p.confidence]]):popup(`${p.carrier} rail crossing`,[['Feature',p.feature_id],['Station',`${p.station_ft} ft`],['Subdivision',p.subdivision],['Status',p.status]]));l.on('click',()=>selectFeature(p.feature_id,false))}});
  state.layers[name]=layer;if(state.visible[name])layer.addTo(map);
}
function toggleLayer(name,visible){state.visible[name]=visible;if(visible&&!state.data[name]){loadLayer(name).then(()=>addLayer(name));return}if(visible&&!state.layers[name])addLayer(name);else if(visible)state.layers[name].addTo(map);else if(state.layers[name])map.removeLayer(state.layers[name]);if(name==='parcels'&&visible)toast('Parcels are public tax-map context, not legal ROW.')}
async function loadLayer(name){if(state.data[name])return state.data[name];const response=await fetch(layerUrls[name]);if(!response.ok)throw Error(`${name} failed to load`);state.data[name]=await response.json();return state.data[name]}
function updateStats(){const feats=state.data.routes.features.filter(f=>displayScope(f.properties.route_part));const miles=feats.reduce((n,f)=>n+f.properties.length_ft,0)/5280;const pdf=feats.filter(f=>f.properties.candidate_pdf_count>0).length;const links=feats.reduce((n,f)=>n+f.properties.utility_links,0);$('statMiles').innerHTML=`${miles.toFixed(2)} <small>mi</small>`;$('statFeaturesLabel').textContent=`${feats.length} features in view`;$('statDocs').innerHTML=`${pdf} <small>/ ${feats.length}</small>`;$('statCleared').innerHTML=`0 <small>/ ${feats.length}</small>`;$('statUtilities').textContent=fmt(links)}
function selectFeature(id,fly){const f=featureFor(id);if(!f)return;const scope=scopeOf(id);if(scope!==state.scope&&state.scope!=='All'){state.scope=scope;updateStats()}state.selected=id;$('insightTitle').textContent='Selected feature';renderSelected(f);redrawRouteStyle();if(fly){const bounds=L.geoJSON(f).getBounds();map.fitBounds(bounds.pad(.35),{maxZoom:14,animate:true})}document.querySelectorAll('.scope-switch button').forEach(b=>{const active=b.dataset.scope===state.scope;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
function renderWatchlist(){state.selected=null;$('insightTitle').textContent='Decision watchlist';const items=watchlist.filter(w=>state.scope==='All'||w.scope===state.scope);$('insightBody').innerHTML=items.map(w=>`<button class="watch-item" data-focus="${esc(w.feature)}"><div class="watch-top"><span>${esc(w.rank)}</span><span>${esc(w.feature)}</span></div><strong>${esc(w.title)}</strong><p>${esc(w.body)}</p></button>`).join('')||'<div class="loading">Select a route scope to view its priority issues.</div>';document.querySelectorAll('.watch-item').forEach(b=>b.addEventListener('click',()=>selectFeature(b.dataset.focus,true)));redrawRouteStyle()}
function renderSelected(f){const p=f.properties;const relevant=watchlist.filter(w=>w.feature===p.feature_id);$('insightBody').innerHTML=`<div class="feature-head"><button class="back-link" id="backWatch">← BACK TO WATCHLIST</button><h3>${esc(p.feature_id)}</h3><div class="feature-sub">${esc(p.route_part)} · ${fmt(p.length_ft)} ft · source label: ${esc(p.source_label)}</div></div><div class="feature-alert">HOLD · Construction side, legal ROW and utility clearance are unverified.</div>${relevant.map(w=>`<div class="detail-block"><h4>${esc(w.rank)}</h4><p>${esc(w.title)} — ${esc(w.body)}</p></div>`).join('')}<div class="detail-block"><h4>JURISDICTION CONTEXT</h4><div class="detail-pills">${[...p.counties,...p.places,...p.townships].slice(0,9).map(x=>`<span class="detail-pill">${esc(x)}</span>`).join('')||'<span class="detail-pill">Boundary open</span>'}</div><p style="margin-top:9px">Road controller is a GIS candidate. Confirm from road acceptance, ROW plans and the work footprint.</p></div><div class="detail-block"><h4>EVIDENCE STATUS</h4><div class="detail-pair"><span>Candidate PDFs</span><b>${p.candidate_pdf_count} · grade ${esc(p.pdf_grade)}</b></div><div class="detail-pair"><span>Utility links within 250 ft</span><b>${fmt(p.utility_links)}</b></div><div class="detail-pair"><span>Water / rail cases</span><b>${p.water_cases} / ${p.rail_crossing_records}</b></div><div class="detail-pair"><span>Mapped ROW</span><b>${esc(p.mapped_row_sources||'No polygon lead')}</b></div></div><button class="detail-action" id="featureEvidence">OPEN FEATURE EVIDENCE ↗</button>`;$('backWatch').addEventListener('click',renderWatchlist);$('featureEvidence').addEventListener('click',()=>openReport(p.candidate_pdf_count?'documents':'missing',p.feature_id))}
function setScope(scope){state.scope=scope;state.selected=null;document.querySelectorAll('.scope-switch button').forEach(b=>{const active=b.dataset.scope===scope;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});updateStats();renderWatchlist();fitScope()}
function openReport(kind,query=''){if(kind==='overview'){closeReport();return}state.report=kind;state.reportLimit=60;const cfg=reports[kind];$('reportKicker').textContent=cfg.kicker;$('reportTitle').textContent=cfg.title;$('reportSubtitle').textContent=cfg.subtitle;$('reportSearch').value=query;$('reportScope').value='All';$('reportDrawer').classList.add('open');$('reportDrawer').setAttribute('aria-hidden','false');$('reportBackdrop').hidden=false;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.report===kind));renderReport();setTimeout(()=>$('reportSearch').focus(),150)}
function closeReport(){state.report='overview';$('reportDrawer').classList.remove('open');$('reportDrawer').setAttribute('aria-hidden','true');$('reportBackdrop').hidden=true;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.report==='overview'))}
function recordScope(r){if(r.route_area==='Chicago'||r.route_area==='S0')return r.route_area;if(r.route_area==='S1')return 'S1';return scopeOf(r.feature_id||r.route_features||r.route_area||r.route_feature_station)}
function filteredRecords(){const cfg=reports[state.report];if(!cfg)return[];const q=$('reportSearch').value.trim().toLowerCase();const scope=$('reportScope').value;return cfg.records().filter(r=>{const rowScope=recordScope(r);const scopeOK=scope==='All'||rowScope===scope||scope==='Chicago'&&rowScope==='Chicago'||(r.route_area==='S0/S1'&&(scope==='S0'||scope==='S1'));return scopeOK&&(!q||JSON.stringify(r).toLowerCase().includes(q))})}
function fieldsFor(r){return Object.entries(r).filter(([k,v])=>v!==''&&v!==null&&v!==undefined&&k!=='relative_path').map(([k,v])=>`<div class="record-field"><b>${esc(k.replaceAll('_',' '))}</b><span>${esc(v)}</span></div>`).join('')}
function renderReport(){const cfg=reports[state.report];if(!cfg)return;state.filtered=filteredRecords();const shown=state.filtered.slice(0,state.reportLimit);$('reportCount').textContent=`${fmt(state.filtered.length)} records${state.filtered.length!==cfg.records().length?' matching filters':''}`;$('reportRows').innerHTML=shown.map((r,i)=>{const fid=r.feature_id||String(r.route_features||r.route_feature_station||'').match(/(?:S0|S1|Spur[1-4])-[^;,: ]+/)?.[0]||'';const url=r.official_source_url||r.source_links||r.source_url||r.source_index_or_portal;return `<details class="report-record"><summary><span class="record-index">${String(i+1).padStart(2,'0')}</span><span class="record-main"><strong>${esc(cfg.titleRow(r))}</strong><small>${esc(cfg.subRow(r))}</small></span><span class="record-chevron">›</span></summary><div class="record-detail">${fieldsFor(r)}<div class="record-actions">${fid?`<button data-focus="${esc(fid)}">FOCUS MAP ↗</button>`:''}${htmlLink(url,'OPEN SOURCE')}</div></div></details>`}).join('')||'<div class="loading">No records match. Try a feature ID, road name, owner or jurisdiction.</div>';$('loadMore').hidden=shown.length>=state.filtered.length;document.querySelectorAll('.record-actions button[data-focus]').forEach(b=>b.addEventListener('click',()=>{const fid=b.dataset.focus;closeReport();selectFeature(fid,true)}))}
function exportCsv(){if(!reports[state.report])return;const rows=state.filtered;if(!rows.length){toast('No matching rows to export');return}const fields=[...new Set(rows.flatMap(r=>Object.keys(r)))];const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv='\ufeff'+[fields.map(quote).join(','),...rows.map(r=>fields.map(k=>quote(r[k])).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`lightpath-${state.report}-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}

async function init(){try{if(window.__ATLAS_DATA__){Object.assign(state.data,window.__ATLAS_DATA__)}else{const [meta,reportsData]=await Promise.all(['data/meta.json','data/reports.json'].map(p=>fetch(p).then(r=>{if(!r.ok)throw Error(p);return r.json()})));state.data.meta=meta;state.data.reports=reportsData}await Promise.all(['routes','row','utilities','water','rail'].map(loadLayer));['routes','row','utilities','water','rail'].forEach(addLayer);const sources=[...new Set(state.data.utilities.features.map(f=>f.properties.source))].sort();$('utilitySource').innerHTML='<option value="all">All utility sources</option>'+sources.map(s=>`<option value="${esc(s.toLowerCase())}">${esc(s)}</option>`).join('');setScope('S0');setTimeout(()=>map.invalidateSize(),200)}catch(error){console.error(error);$('insightBody').innerHTML='<div class="loading">The map data could not load. Rebuild the data bundle with python build_data.py.</div>';toast('Map data could not load.')}}
document.querySelectorAll('.scope-switch button').forEach(b=>b.addEventListener('click',()=>setScope(b.dataset.scope)));
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>openReport(b.dataset.report)));
document.querySelectorAll('input[data-layer]').forEach(c=>c.addEventListener('change',()=>toggleLayer(c.dataset.layer,c.checked)));
$('utilitySource').addEventListener('change',e=>{state.utilitySource=e.target.value;addLayer('utilities')});
$('utilityType').addEventListener('change',e=>{state.utilityType=e.target.value;addLayer('utilities')});
$('fitButton').addEventListener('click',fitScope);
$('baseButton').addEventListener('click',()=>{map.removeLayer(baseLayers[state.base]);state.base=state.base==='dark'?'light':'dark';baseLayers[state.base].addTo(map);baseLayers[state.base].bringToBack();toast(`${state.base==='dark'?'Dark':'Light'} basemap`)});
$('layersButton').addEventListener('click',()=>{const p=$('layersPanel');p.hidden=!p.hidden;$('layersButton').classList.toggle('active',!p.hidden);$('layersButton').setAttribute('aria-expanded',String(!p.hidden))});
$('closeReport').addEventListener('click',closeReport);$('reportBackdrop').addEventListener('click',closeReport);$('reportSearch').addEventListener('input',()=>{state.reportLimit=60;renderReport()});$('reportScope').addEventListener('change',()=>{state.reportLimit=60;renderReport()});$('exportReport').addEventListener('click',exportCsv);$('loadMore').addEventListener('click',()=>{state.reportLimit+=60;renderReport()});
$('helpButton').addEventListener('click',()=>$('helpDialog').showModal());document.addEventListener('keydown',e=>{if(e.key==='Escape')closeReport()});
init();
